import{_ as a,c as l,a as n,o as s}from"./app-B9IyngIV.js";const i={};function t(p,e){return s(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="利尔化学工作总结" tabindex="-1"><a class="header-anchor" href="#利尔化学工作总结"><span>利尔化学工作总结</span></a></h1><div style="background:#f8f9fa;padding:12px 16px;border-left:3px solid #4CAF50;margin-bottom:16px;border-radius:0 4px 4px 0;font-size:0.9rem;"><div style="display:flex;align-items:center;gap:30px;flex-wrap:wrap;"><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">📅</span><span>2025-07-27</span></div><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">✍️</span><span>Jixer</span></div></div></div> ## 开篇 <p>本文章用于记录笔者在利尔化学中做 Java 全栈开发的每月的工作总结</p><h2 id="_2025-6-梦的开始" tabindex="-1"><a class="header-anchor" href="#_2025-6-梦的开始"><span>2025.6（梦的开始）</span></a></h2><p>本月是 10 号入职的，与笔者一起入职的还有另一位小伙伴（也是25届应届生）。第一天拉取了代码配置了环境（好家伙，一看发现是若依二开项目），第二天就开始写需求代码了，这里的需求很复杂，但代码简单，后端基本都是一些简单的 CRUD。领导让我跟着带我的那个同事一起开发研发管理模块， 另一个小伙伴则是跟着另一个人改 BUG。第一周过完，领导请我们部门聚餐（还以为是为了庆祝新员工呢，结果目的是为了请另一个领导吃饭）。总的来说，这里工作给我的感觉就是压力不大，可以利用下班时间好好专研其他的东西。</p><h2 id="_2025-7-逐渐融入" tabindex="-1"><a class="header-anchor" href="#_2025-7-逐渐融入"><span>2025.7（逐渐融入）</span></a></h2><p>本月将研发模块开发完成了，负责交给一位同事进行测试，给我们找出了150多个 BUG，我负责完成了50多个，另外的100个由另一个带我的同事完成。这个月参加了长达一周的新员工入职培训，培训是由公司的高层来给我们授课，主要的内容是关于介绍公司的一些基本情况和建议（PS：我反正是没听，全称干自己的事情去了），最让我有点开心的是这次入职培训送了一个小米水杯、一个带有利尔化学 LOGO 的书包、一个笔记本和一支笔，哦对了，这次培训还是住的酒店，我那间房是个电竞房，爽得不要太爽，这种入职培训是很多我这个级别进入的互联网公司感受不到的，仪式感拉满。领导给我安排了一个人工客服的活（我心想这不跟我之前的做的 mallchat 一样吗，简单的嘞，拿来用行）。另一个小伙伴做的搭建 AI，只能说难评，我还以为他能做出什么厉害的，结果 RAG 这个流程都要调用其他第三方工具的接口。好了，这月差不多就这些，完毕。</p><h2 id="_2025-8" tabindex="-1"><a class="header-anchor" href="#_2025-8"><span>2025.8</span></a></h2><p>这个月过的很快，个人感觉这个月工作量很少，大部分的时间花在了人工客服模块的开发上，也是将客服和客户以及内部实时通讯的交流沟通完成了大概。此外我还参与了 ALM 系统的开发，我现在都没明白为什么这个是叫单独的系统，可能是我做的业务比较边缘（几张表的 CRUD），没有设计核心部分的开发。然后呢我也对研发管理模块上线前出现的问题进行了修复，搞笑的是这部分的内容改来改去，最终又改回去了</p><p>人工客服模块我要单独吐槽一下，这部分没有明确的需求文档、原型设计，领导想让我一个月从0到1开发出来，我自己定的目标就是实现简单的沟通，好家伙，领导想让我直接上线，难崩。所有的东西都是参考开源的项目，做出来了又不符合要求，我这个月都开了4次会议来确定这部分内容的需求了，要是给我一个需求文档也不会搞的这样难受</p><h2 id="_2025-9" tabindex="-1"><a class="header-anchor" href="#_2025-9"><span>2025.9</span></a></h2><p>9月这个是我最空闲的一个月，没有开发的事干，因为上个月的人工客服没有部署上线，所以这个月任然继续完成人工客服 + 内部通讯，本月有进展是将内部通讯全部迁移到了桌面端，并且支持无感登录网页端的自建平台（采用的是中转页跳转的方法）。大部分的时间我都在干自己的项目，感觉我的主观能动性降低了，随着在这家公司干，越来越缺乏上班的动力和激情，工作时间感觉不饱和，每天的个人预期开发量和思考量不达标。我总是想着公司没活干，自己找活干的思想，可最近我越来越找不到对项目的嗅觉和灵感了，在一个工作流项目上死磕，希望下个月能够有活干，不然如果继续这样，我真觉得明年翻年我就得跑路找下家了，一点进步都没有，思想不能变得麻木</p><h2 id="_2025-10" tabindex="-1"><a class="header-anchor" href="#_2025-10"><span>2025.10</span></a></h2><p>10月，部长看完之前做的桌面端内部通讯不错，让我接着做这个，本月对这个系统新加了内部小程序功能、并且对整体的页面和推送功能都做了很大的完善，目前已经上线了生产环境，正在给我们开发部门内部先自己使用。当然这期间也陆陆续续的出现很多问题，问题都整理成了一个 Excel 表格。部长让我每周自己主动组织开会一次介绍下当前的 IM 系统开发进度，怎么说呢，之前在学校也做个类似的即时通讯项目，但未真正使用，这次要考虑到正式使用，所以很多点都需要考虑，比如：系统是否能够承受的住日活 800 人的并发量，查询速度是否满足要求，是否有必要上缓存、页面美观等因素，总之还是挺有意思的，我一个人做完还是有难度</p><h2 id="_2025-11" tabindex="-1"><a class="header-anchor" href="#_2025-11"><span>2025.11</span></a></h2><blockquote><p>待完善...</p></blockquote><h2 id="阅读的文章" tabindex="-1"><a class="header-anchor" href="#阅读的文章"><span>阅读的文章</span></a></h2><ul><li>https://blog.csdn.net/JDDTechTalk/article/details/141888052?spm=1001.2014.3001.5501：介绍了一个系统如何做好高性能、高并发、<strong>高可用</strong>（最重要的）</li><li></li></ul>',19)])])}const d=a(i,[["render",t]]),h=JSON.parse('{"path":"/%E6%9D%82%E8%B0%88/%E5%88%A9%E5%B0%94%E5%8C%96%E5%AD%A6%E5%B7%A5%E4%BD%9C%E6%80%BB%E7%BB%93.html","title":"利尔化学工作总结","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"2025.6（梦的开始）","slug":"_2025-6-梦的开始","link":"#_2025-6-梦的开始","children":[]},{"level":2,"title":"2025.7（逐渐融入）","slug":"_2025-7-逐渐融入","link":"#_2025-7-逐渐融入","children":[]},{"level":2,"title":"2025.8","slug":"_2025-8","link":"#_2025-8","children":[]},{"level":2,"title":"2025.9","slug":"_2025-9","link":"#_2025-9","children":[]},{"level":2,"title":"2025.10","slug":"_2025-10","link":"#_2025-10","children":[]},{"level":2,"title":"2025.11","slug":"_2025-11","link":"#_2025-11","children":[]},{"level":2,"title":"阅读的文章","slug":"阅读的文章","link":"#阅读的文章","children":[]}],"git":{},"filePathRelative":"杂谈/利尔化学工作总结.md"}');export{d as comp,h as data};
